     4→ */
     5→import React, { useState } from 'react';
     6→import {
     7→  Box,
     8→  IconButton,
     9→  Menu,
    10→  MenuItem,
    11→  Avatar,
    12→  Typography,
    13→  Divider,
    14→  ListItemIcon,
    15→  CircularProgress,
    16→  Chip,
    17→} from '@mui/material';
    18→import {
    19→  Logout as LogoutIcon,
    20→  Person as PersonIcon,
    21→  ExpandMore as ExpandMoreIcon,
    22→  Brightness4 as DarkModeIcon,
    23→  Brightness7 as LightModeIcon,
    24→} from '@mui/icons-material';
    25→import { useNavigate } from 'react-router-dom';
    26→import { useAuth } from '../../hooks/useAuth';
    27→import { useThemeMode } from '../../hooks/useThemeMode';
    28→
    29→const FKUserMenu: React.FC = () => {
    30→  const navigate = useNavigate();
    31→  const { user, userProfile, signOut, loading } = useAuth();
    32→  const { isDarkMode, toggleTheme } = useThemeMode();
    33→  const [anchorEl, setAnchorEl] = useState<null | HTMLElement>(null);
    34→  const [isLoggingOut, setIsLoggingOut] = useState(false);
    35→
    36→  const open = Boolean(anchorEl);
    37→
    38→  const handleClick = (event: React.MouseEvent<HTMLElement>) => {
    39→    setAnchorEl(event.currentTarget);
    40→  };
    41→
    42→  const handleClose = () => {
    43→    setAnchorEl(null);
    44→  };
    45→
    46→  const handleLogout = async () => {
    47→    setIsLoggingOut(true);
    48→    handleClose();
    49→
    50→    try {
    51→      await signOut();
    52→      navigate('/login', { replace: true });
    53→    } catch (error) {
    54→      console.error('Error logging out:', error);
    55→      // Still navigate to login even if sign out fails
    56→      navigate('/login', { replace: true });
    57→    } finally {
    58→      setIsLoggingOut(false);
    59→    }
    60→  };
    61→
    62→  // Get user initials for avatar
    63→  const getInitials = (name: string): string => {
    64→    const parts = name.trim().split(' ');
    65→    if (parts.length >= 2) {
    66→      return `${parts[0][0]}${parts[1][0]}`.toUpperCase();
    67→    }
    68→    return name.substring(0, 2).toUpperCase();
    69→  };
    70→
    71→  // Get role label in Spanish
    72→  const getRoleLabel = (role: string): string => {
    73→    const roleLabels: Record<string, string> = {
    74→      admin: 'Administrador',
    75→      legal: 'Legal',
    76→      operations: 'Operaciones',
    77→      commercial: 'Comercial',
    78→      analyst: 'Analista',
    79→      mesa_control: 'Mesa de Control',
    80→      manager: 'Gerente',
    81→      user: 'Usuario',
    82→      cliente: 'Cliente',
    83→    };
    84→    return roleLabels[role] || role;
    85→  };
    86→
    87→  // Get user type badge color
    88→  const getUserTypeBadgeColor = (userType: string) => {
    89→    return userType === 'cliente' ? 'secondary' : 'primary';
    90→  };
    91→
    92→  // Only show loading spinner on initial load (when we don't have user data yet)
    93→  // Once we have user profile, keep showing it even if there's a background refresh
    94→  if (!user && loading) {
    95→    return (
    96→      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
    97→        <CircularProgress size={24} sx={{ color: 'white' }} />
    98→      </Box>
    99→    );
   100→  }
   101→
   102→  // If we have user but no profile yet, show loading
   103→  if (user && !userProfile && loading) {
   104→    return (
   105→      <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
   106→        <CircularProgress size={24} sx={{ color: 'white' }} />
   107→      </Box>
   108→    );
   109→  }
   110→
   111→  // If we have user but profile failed to load, show minimal user info
   112→  if (user && !userProfile) {
   113→    return (
   114→      <Box>
   115→        <IconButton
   116→          size="small"
   117→          sx={{
   118→            gap: 1.5,
   119→            px: 1.5,
   120→            py: 0.5,
   121→            borderRadius: 2,
   122→            backgroundColor: 'rgba(255, 255, 255, 0.1)',
   123→            '&:hover': {
   124→              backgroundColor: 'rgba(255, 255, 255, 0.2)',
   125→            },
   126→          }}
   127→        >
   128→          <Avatar
   129→            sx={{
   130→              width: 36,
   131→              height: 36,
   132→              bgcolor: 'coral.main',
   133→              fontSize: '0.875rem',
   134→              fontWeight: 600,
   135→            }}
   136→          >
   137→            {user.email ? user.email.substring(0, 2).toUpperCase() : '??'}
   138→          </Avatar>
   139→          <Box sx={{ display: { xs: 'none', md: 'block' }, textAlign: 'left' }}>
   140→            <Typography
   141→              variant="body2"
   142→              sx={{ color: 'white', fontWeight: 600, lineHeight: 1.2 }}
   143→            >
   144→              {user.email || 'Usuario'}
   145→            </Typography>
   146→          </Box>
   147→        </IconButton>
   148→      </Box>
   149→    );
   150→  }
   151→
   152→  // TypeScript guard: if we reach here, userProfile must exist
   153→  if (!userProfile) {
   154→    return null;
   155→  }
   156→
   157→  return (
   158→    <Box>
   159→      {/* User Button */}
   160→      <IconButton
   161→        onClick={handleClick}
   162→        size="small"
   163→        sx={{
   164→          gap: 1.5,
   165→          px: 1.5,
   166→          py: 0.5,
   167→          borderRadius: 2,
   168→          backgroundColor: 'rgba(255, 255, 255, 0.1)',
   169→          '&:hover': {
   170→            backgroundColor: 'rgba(255, 255, 255, 0.2)',
   171→          },
   172→        }}
   173→        aria-controls={open ? 'user-menu' : undefined}
   174→        aria-haspopup="true"
   175→        aria-expanded={open ? 'true' : undefined}
   176→      >
   177→        <Avatar
   178→          sx={{
   179→            width: 36,
   180→            height: 36,
   181→            bgcolor: 'coral.main',
   182→            fontSize: '0.875rem',
   183→            fontWeight: 600,
   184→          }}
   185→        >
   186→          {getInitials(userProfile.full_name)}
   187→        </Avatar>
   188→        <Box sx={{ display: { xs: 'none', md: 'block' }, textAlign: 'left' }}>
   189→          <Typography
   190→            variant="body2"
   191→            sx={{ color: 'white', fontWeight: 600, lineHeight: 1.2 }}
   192→          >
   193→            {userProfile.full_name}
   194→          </Typography>
   195→          <Typography
   196→            variant="caption"
   197→            sx={{ color: 'rgba(255, 255, 255, 0.7)', lineHeight: 1 }}
   198→          >
