/**
 * Legal Department Dashboard
 */
import React, { useState, useEffect } from 'react';
import {
  Box,
  Typography,
  Card,
  CardContent,
  Tabs,
  Tab,
  Grid,
} from '@mui/material';
import {
  Assignment as AssignmentIcon,
  RateReview as ReviewIcon,
  CloudUpload as UploadIcon,
  Assessment as StatsIcon,
  Today as TodayIcon,
} from '@mui/icons-material';
import { legalService } from '../../services/legalService';
import FKClientDataImport from '../../components/forms/FKClientDataImport';
import FKReviewQueue from '../../components/forms/FKReviewQueue';

interface TabPanelProps {
  children?: React.ReactNode;
  index: number;
  value: number;
}

function TabPanel(props: TabPanelProps) {
  const { children, value, index, ...other } = props;

  return (
    <div
      role="tabpanel"
      hidden={value !== index}
      id={`legal-tabpanel-${index}`}
      aria-labelledby={`legal-tab-${index}`}
      {...other}
    >
      {value === index && <Box sx={{ py: 3 }}>{children}</Box>}
    </div>
  );
}

const LegalDashboard: React.FC = () => {
  const [currentTab, setCurrentTab] = useState(0);
  const [stats, setStats] = useState({
    total_generated: 0,
    pending_review: 0,
    approved: 0,
    rejected: 0,
    generated_today: 0,
  });

  useEffect(() => {
    loadStats();
  }, []);

  const loadStats = async () => {
    try {
      const data = await legalService.getContractStats();
      setStats(data);
    } catch (error) {
      console.error('Error loading stats:', error);
    }
  };

  const handleTabChange = (_event: React.SyntheticEvent, newValue: number) => {
    setCurrentTab(newValue);
  };

  return (
    <Box>
      {/* Header */}
      <Box sx={{ mb: 4 }}>
        <Typography variant="h4" gutterBottom sx={{ fontWeight: 700, color: 'primary.dark' }}>
          Departamento Legal
        </Typography>
        <Typography variant="body1" sx={{ color: 'grey.700' }}>
          Revisión y aprobación de contratos
        </Typography>
      </Box>

      {/* Stats Cards */}
      <Grid container spacing={3} sx={{ mb: 4 }}>
        <Grid size={{ xs: 12, sm: 6, md: 3 }}>
          <Card>
            <CardContent>
              <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                <AssignmentIcon sx={{ fontSize: 40, color: 'primary.main' }} />
                <Box>
                  <Typography variant="h4" sx={{ fontWeight: 700 }}>
                    {stats.total_generated}
                  </Typography>
                  <Typography variant="body2" color="text.secondary">
                    Total Generados
                  </Typography>
                </Box>

/**
 * Type definitions for the Finkargo theme system
 * Supports light and dark mode themes with persistent user preferences
 */

/**
 * Theme mode type - defines available theme options
 */
export type ThemeMode = 'light' | 'dark';

/**
 * Theme context interface - provides theme state and control functions
 */
export interface ThemeContextType {
  /** Current active theme mode */
  mode: ThemeMode;
  /** Toggle between light and dark themes */
  toggleTheme: () => void;
  /** Set a specific theme mode */
  setTheme: (mode: ThemeMode) => void;
  /** Computed boolean indicating if dark mode is active */
  isDarkMode: boolean;
}

/**
 * localStorage key for persisting theme preference
 */
export const THEME_STORAGE_KEY = 'finkargo_theme_mode';

/**
 * Default theme mode when no preference is stored
 */
export const DEFAULT_THEME_MODE: ThemeMode = 'light';
